#include <iostream>

int* risky() {
    int x = 42;        // automatic storage, dies at return
    return &x;         // BUG: dangling pointer
}

int main() {
    int* p = risky();  // p is non-null but points at a dead object
    // std::cout << *p;   // reading *p is undefined behaviour
    std::cout << "p non-null: " << (p != nullptr) << '\n';  // prints 1
}

#include <iostream>

int main() {
    int* p = new int(7);
    delete p;
    // *p = 9;       // use-after-free: undefined behaviour
    p = nullptr;     // hygiene: nothing to free, nothing to read
    delete p;        // safe no-op, guaranteed
}

#include <iostream>

struct Report {
    ~Report() { std::cout << "Report destroyed\n"; }
};

int main() {
    Report* r = new Report();
    Report* alias = r;   // two pointers, ONE object, no ownership agreement
    delete r;
    // delete alias;    // BUG: double delete - heap corruption
}

#include <iostream>
#include <stdexcept>

void handle_order(int id) {
    int* audit = new int(id);          // acquired
    if (id < 0) {
        throw std::invalid_argument("bad order id");  // audit LEAKS here
    }
    delete audit;                      // reached only on the happy path
}

int main() {
    try { handle_order(-1); } catch (const std::exception&) { /* logged */ }
}

